module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiComboBox,\n  EuiFieldText,\n  EuiFormRow,\n  EuiFilePicker,\n  EuiRange,\n  EuiSelect,\n  EuiSwitch,\n  EuiPanel,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isSwitchChecked: false,\n      comboBoxSelectionOptions: [],\n      value: '20',\n    };\n  }\n\n  onRangeChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  onSwitchChange = () => {\n    this.setState({\n      isSwitchChecked: !this.state.isSwitchChecked,\n    });\n  };\n\n  render() {\n    return (\n      <EuiPanel style={{ maxWidth: 300 }}>\n        <EuiFormRow\n          label=\"Text field\"\n          helpText=\"I am some friendly help text.\"\n          display=\"columnCompressed\">\n          <EuiFieldText name=\"first\" isLoading compressed />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Select\" display=\"columnCompressed\">\n          <EuiSelect\n            options={[\n              { value: 'option_one', text: 'Option one' },\n              { value: 'option_two', text: 'Option two' },\n              { value: 'option_three', text: 'Option three' },\n            ]}\n            compressed\n          />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"File picker\" display=\"columnCompressed\">\n          <EuiFilePicker compressed display=\"default\" />\n        </EuiFormRow>\n\n        <EuiFormRow\n          label=\"Comboboxwithalonglabelname\"\n          display=\"columnCompressed\">\n          <EuiComboBox\n            options={[\n              { label: 'Option one' },\n              { label: 'Option two' },\n              { label: 'Option three' },\n            ]}\n            compressed\n            selectedOptions={this.state.comboBoxSelectionOptions}\n            onChange={comboBoxSelectionOptions =>\n              this.setState({ comboBoxSelectionOptions })\n            }\n          />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Range\" display=\"columnCompressed\">\n          <EuiRange\n            min={0}\n            max={100}\n            name=\"range\"\n            id=\"range\"\n            showInput\n            compressed\n            value={this.state.value}\n            onChange={this.onRangeChange}\n          />\n        </EuiFormRow>\n\n        <EuiFormRow display=\"columnCompressedSwitch\" label=\"Swtich\">\n          <EuiSwitch\n            name=\"switch\"\n            checked={this.state.isSwitchChecked}\n            onChange={this.onSwitchChange}\n            compressed\n          />\n        </EuiFormRow>\n      </EuiPanel>\n    );\n  }\n}\n"