module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiColorPicker,\n  EuiButton,\n  EuiPopover,\n  EuiFormRow,\n  EuiModal,\n  EuiModalBody,\n  EuiModalHeader,\n  EuiModalHeaderTitle,\n  EuiOverlayMask,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      color: '#FFF',\n      isModalVisible: false,\n      isPopoverOpen: false,\n    };\n  }\n\n  closeModal = () => {\n    this.setState({ isModalVisible: false });\n  };\n\n  showModal = () => {\n    this.setState({ isModalVisible: true });\n  };\n\n  togglePopover = () => {\n    this.setState(prevState => ({\n      isPopoverOpen: !prevState.isPopoverOpen,\n    }));\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  onChange = color => {\n    this.setState({\n      color,\n    });\n  };\n\n  render() {\n    const { color, isModalVisible, isPopoverOpen } = this.state;\n\n    const colorPicker = (\n      <EuiColorPicker color={color} onChange={this.onChange} />\n    );\n\n    const button = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.togglePopover}>\n        Open popover\n      </EuiButton>\n    );\n\n    let modal;\n\n    if (isModalVisible) {\n      modal = (\n        <EuiOverlayMask>\n          <EuiModal onClose={this.closeModal} style={{ width: '800px' }}>\n            <EuiModalHeader>\n              <EuiModalHeaderTitle>Color picker in a modal</EuiModalHeaderTitle>\n            </EuiModalHeader>\n\n            <EuiModalBody>\n              <EuiFormRow label=\"Color picker\">{colorPicker}</EuiFormRow>\n            </EuiModalBody>\n          </EuiModal>\n        </EuiOverlayMask>\n      );\n    }\n\n    return (\n      <Fragment>\n        <EuiFormRow\n          label=\"Color picker\"\n          helpText=\"This color picker is inside of a form row\">\n          {colorPicker}\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Unruly focus management\">\n          <EuiPopover\n            id=\"popover\"\n            ownFocus={true}\n            button={button}\n            isOpen={isPopoverOpen}\n            closePopover={this.closePopover}>\n            <div style={{ width: '300px' }}>\n              <EuiFormRow label=\"Color picker\">{colorPicker}</EuiFormRow>\n            </div>\n          </EuiPopover>\n        </EuiFormRow>\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiButton onClick={this.showModal}>Show modal</EuiButton>\n\n        {modal}\n      </Fragment>\n    );\n  }\n}\n"