module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiPopover,\n  EuiPopoverTitle,\n  EuiPopoverFooter,\n  EuiButton,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiText,\n  EuiTextColor,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n  }\n\n  onButtonClick1() {\n    this.setState({\n      isPopoverOpen1: !this.state.isPopoverOpen1,\n    });\n  }\n\n  closePopover1() {\n    this.setState({\n      isPopoverOpen1: false,\n    });\n  }\n\n  onButtonClick2() {\n    this.setState({\n      isPopoverOpen2: !this.state.isPopoverOpen2,\n    });\n  }\n\n  closePopover2() {\n    this.setState({\n      isPopoverOpen2: false,\n    });\n  }\n\n  onButtonClick3() {\n    this.setState({\n      isPopoverOpen3: !this.state.isPopoverOpen3,\n    });\n  }\n\n  closePopover3() {\n    this.setState({\n      isPopoverOpen3: false,\n    });\n  }\n\n  render() {\n    return (\n      <EuiFlexGroup>\n        <EuiFlexItem grow={false}>\n          <EuiPopover\n            id=\"withTitle\"\n            ownFocus\n            button={\n              <EuiButton\n                iconType=\"arrowDown\"\n                iconSide=\"right\"\n                onClick={this.onButtonClick1.bind(this)}>\n                With title\n              </EuiButton>\n            }\n            isOpen={this.state.isPopoverOpen1}\n            closePopover={this.closePopover1.bind(this)}\n            anchorPosition=\"downCenter\">\n            <EuiPopoverTitle>Hello, I&rsquo;m a popover title</EuiPopoverTitle>\n            <div style={{ width: '300px' }}>\n              <EuiText>\n                <p>\n                  Selfies migas stumptown hot chicken quinoa wolf green juice,\n                  mumblecore tattooed trust fund hammock truffaut taxidermy\n                  kogi.\n                </p>\n              </EuiText>\n            </div>\n          </EuiPopover>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiPopover\n            id=\"withFooter\"\n            ownFocus\n            button={\n              <EuiButton\n                iconType=\"arrowDown\"\n                iconSide=\"right\"\n                onClick={this.onButtonClick2.bind(this)}>\n                With footer\n              </EuiButton>\n            }\n            isOpen={this.state.isPopoverOpen2}\n            closePopover={this.closePopover2.bind(this)}\n            anchorPosition=\"upCenter\">\n            <div style={{ width: '300px' }}>\n              <EuiText>\n                <p>\n                  Selfies migas stumptown hot chicken quinoa wolf green juice,\n                  mumblecore tattooed trust fund hammock truffaut taxidermy\n                  kogi.\n                </p>\n              </EuiText>\n            </div>\n            <EuiPopoverFooter>\n              <EuiTextColor color=\"subdued\">\n                Hello, I&rsquo;m a small popover footer caption\n              </EuiTextColor>\n            </EuiPopoverFooter>\n          </EuiPopover>\n        </EuiFlexItem>\n\n        <EuiFlexItem grow={false}>\n          <EuiPopover\n            id=\"withTitleAndFooter\"\n            ownFocus\n            button={\n              <EuiButton\n                iconType=\"arrowDown\"\n                iconSide=\"right\"\n                onClick={this.onButtonClick3.bind(this)}>\n                With title and footer button\n              </EuiButton>\n            }\n            isOpen={this.state.isPopoverOpen3}\n            closePopover={this.closePopover3.bind(this)}\n            anchorPosition=\"upCenter\">\n            <EuiPopoverTitle>Hello, I&rsquo;m a popover title</EuiPopoverTitle>\n            <div style={{ width: '300px' }}>\n              <EuiText>\n                <p>\n                  Selfies migas stumptown hot chicken quinoa wolf green juice,\n                  mumblecore tattooed trust fund hammock truffaut taxidermy\n                  kogi.\n                </p>\n              </EuiText>\n            </div>\n            <EuiPopoverFooter>\n              <EuiButton fullWidth size=\"s\">\n                Manage this thing\n              </EuiButton>\n            </EuiPopoverFooter>\n          </EuiPopover>\n        </EuiFlexItem>\n      </EuiFlexGroup>\n    );\n  }\n}\n"