module.exports = "/* eslint react/no-multi-comp: 0 */\n/* eslint react/prefer-stateless-function: 0 */\n\nimport React, { Component } from 'react';\n\nimport {\n  EuiAccordion,\n  EuiButton,\n  EuiSpacer,\n  EuiText,\n} from '../../../../src/components';\n\nclass Rows extends Component {\n  state = {\n    counter: 1,\n  };\n\n  onIncrease() {\n    this.setState(prevState => ({\n      counter: prevState.counter + 1,\n    }));\n  }\n\n  onDecrease() {\n    this.setState(prevState => ({\n      counter: Math.max(0, prevState.counter - 1),\n    }));\n  }\n\n  render() {\n    const rows = [];\n    for (let i = 1; i <= this.state.counter; i++) {\n      rows.push(<p key={i}>Row {i}</p>);\n    }\n    return (\n      <EuiText>\n        <EuiSpacer size=\"s\" />\n        <p>\n          <EuiButton onClick={() => this.onIncrease()}>\n            Increase height\n          </EuiButton>{' '}\n          <EuiButton onClick={() => this.onDecrease()}>\n            Decrease height\n          </EuiButton>\n        </p>\n        {rows}\n      </EuiText>\n    );\n  }\n}\n\nclass AccordionGrow extends Component {\n  render() {\n    return (\n      <EuiAccordion\n        id=\"accordion1\"\n        buttonContent=\"Click me to toggle close / open\"\n        initialIsOpen={true}\n        paddingSize=\"l\">\n        <Rows />\n      </EuiAccordion>\n    );\n  }\n}\n\nexport default AccordionGrow;\n"