module.exports = "import React, { Component } from 'react';\n\nimport { EuiSuperSelect } from '../../../../src/components';\nimport { DisplayToggles } from '../form_controls/display_toggles';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.options = [\n      {\n        value: 'option_one',\n        inputDisplay: 'Option one',\n        disabled: true,\n        'data-test-subj': 'option one',\n      },\n      {\n        value: 'option_two',\n        inputDisplay: 'Option two',\n      },\n      {\n        value: 'option_three',\n        inputDisplay: (\n          <span className=\"eui-textTruncate eui-displayBlock\">\n            Option three has a super long text and added truncation\n          </span>\n        ),\n      },\n    ];\n\n    this.state = {\n      value: this.options[1].value,\n    };\n  }\n\n  onChange = value => {\n    this.setState({\n      value: value,\n    });\n  };\n\n  render() {\n    return (\n      /* DisplayToggles wrapper for Docs only */\n      <DisplayToggles>\n        <EuiSuperSelect\n          options={this.options}\n          valueOfSelected={this.state.value}\n          onChange={this.onChange}\n        />\n      </DisplayToggles>\n    );\n  }\n}\n"