module.exports = "import React, { useState } from 'react';\nimport {\n  EuiDragDropContext,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiDraggable,\n  EuiDroppable,\n  EuiIcon,\n  EuiPanel,\n} from '../../../../src/components';\n\nimport {\n  euiDragDropMove,\n  euiDragDropReorder,\n} from '../../../../src/components/drag_and_drop';\n\nimport { makeList } from './helper';\n\nexport default () => {\n  const [list1, setList1] = useState(makeList(3));\n  const [list2, setList2] = useState(makeList(3, 4));\n  const onDragEnd = ({ source, destination }) => {\n    const lists = { DROPPABLE_AREA_1: list1, DROPPABLE_AREA_2: list2 };\n    const actions = { DROPPABLE_AREA_1: setList1, DROPPABLE_AREA_2: setList2 };\n    if (source && destination) {\n      if (source.droppableId === destination.droppableId) {\n        const items = euiDragDropReorder(\n          lists[destination.droppableId],\n          source.index,\n          destination.index\n        );\n\n        actions[destination.droppableId](items);\n      } else {\n        const sourceId = source.droppableId;\n        const destinationId = destination.droppableId;\n        const result = euiDragDropMove(\n          lists[sourceId],\n          lists[destinationId],\n          source,\n          destination\n        );\n\n        actions[sourceId](result[sourceId]);\n        actions[destinationId](result[destinationId]);\n      }\n    }\n  };\n  return (\n    <EuiDragDropContext onDragEnd={onDragEnd}>\n      <EuiFlexGroup>\n        <EuiFlexItem>\n          <EuiDroppable\n            droppableId=\"DROPPABLE_AREA_1\"\n            spacing=\"m\"\n            withPanel\n            grow={false}>\n            {list1.length > 0 ? (\n              list1.map(({ content, id }, idx) => (\n                <EuiDraggable spacing=\"m\" key={id} index={idx} draggableId={id}>\n                  {(provided, state) => (\n                    <EuiPanel>\n                      {content}\n                      {state.isDragging && ' ✨'}\n                    </EuiPanel>\n                  )}\n                </EuiDraggable>\n              ))\n            ) : (\n              <EuiFlexGroup\n                alignItems=\"center\"\n                justifyContent=\"spaceAround\"\n                gutterSize=\"none\"\n                style={{ height: '100%' }}>\n                <EuiFlexItem grow={false}>\n                  <EuiIcon type=\"faceSad\" />\n                </EuiFlexItem>\n              </EuiFlexGroup>\n            )}\n          </EuiDroppable>\n        </EuiFlexItem>\n        <EuiFlexItem>\n          <EuiDroppable\n            droppableId=\"DROPPABLE_AREA_2\"\n            spacing=\"m\"\n            withPanel\n            grow={false}>\n            {list2.length > 0 ? (\n              list2.map(({ content, id }, idx) => (\n                <EuiDraggable spacing=\"m\" key={id} index={idx} draggableId={id}>\n                  {(provided, state) => (\n                    <EuiPanel>\n                      {content}\n                      {state.isDragging && ' ✨'}\n                    </EuiPanel>\n                  )}\n                </EuiDraggable>\n              ))\n            ) : (\n              <EuiFlexGroup\n                alignItems=\"center\"\n                justifyContent=\"spaceAround\"\n                gutterSize=\"none\"\n                style={{ height: '100%' }}>\n                <EuiFlexItem grow={false}>\n                  <EuiIcon type=\"faceSad\" />\n                </EuiFlexItem>\n              </EuiFlexGroup>\n            )}\n          </EuiDroppable>\n        </EuiFlexItem>\n      </EuiFlexGroup>\n    </EuiDragDropContext>\n  );\n};\n"